select V.*, P.* from JCR_SVALUE as V, JCR_SITEM as P where P.I_CLASS=2 and P.name='[http://www.jcp.org/jcr/1.0]versionHistory' and (P.P_TYPE is null or P.P_TYPE!=9) and V.PROPERTY_ID = P.ID;

/*date property*/
select V.*, P.* from JCR_SVALUE as V, JCR_SITEM as P where P.I_CLASS=2 and P.name='[http://www.jcp.org/jcr/1.0]created' and (P.P_TYPE is null or P.P_TYPE!=5) and V.PROPERTY_ID = P.ID;
select V.*, P.* from JCR_SVALUE as V, JCR_SITEM as P where P.I_CLASS=2 and P.name='[http://www.jcp.org/jcr/1.0]lastModified' and (P.P_TYPE is null or P.P_TYPE!=5) and V.PROPERTY_ID = P.ID;
select V.*, P.* from JCR_SVALUE as V, JCR_SITEM as P where P.I_CLASS=2 and P.name='[http://www.exoplatform.com/jcr/exo/1.0]dateModified' and (P.P_TYPE is null or P.P_TYPE!=5) and V.PROPERTY_ID = P.ID;
