{code}
It is created via NewUserListener. 
Later, when server started and running. When email is being edited, the same code creating a Node is invoked in NewUserListener. This causes ItemExists exception.

In PLF-3.5-M2 and prior versions, NewUserListener catches exception:

{code}
  public void preSave(User user, boolean isNew)
      throws Exception {
    String userName = user.getUserName();
    prepareSystemWorkspace(userName); 
  }

  private void prepareSystemWorkspace(String userName) throws Exception {
    Session session = null;
    //Manage production workspace
    RepositoryEntry repo = jcrService_.getCurrentRepository().getConfiguration();
    try {
      String defaultWorkspaceName = jcrService_.getDefaultRepository().getConfiguration().getDefaultWorkspaceName() ;
      session = jcrService_.getRepository(repo.getName()).getSystemSession(defaultWorkspaceName);
      Node usersHome = (Node) session.getItem(
          nodeHierarchyCreator_.getJcrPath(BasePath.CMS_USERS_PATH));
      initSystemData(usersHome, userName) ;
      session.save();
      session.logout();
    } catch (RepositoryException re){ <<<<<<<<<<<<<<<<<<<<<<<<
      session.logout();
      return;
    }
  }

  private void initSystemData(Node usersHome, String userName) throws Exception{
    Node userHome = usersHome.getNode(userName) ;
    Node queriesHome =  userHome.getNode(relativePath_) ;
    boolean userFound = false;
    NewUserConfig.User templateConfig = null;
    for (NewUserConfig.User userConfig : config_.getUsers()) {
      String currentName = userConfig.getUserName();
      if (config_.getTemplate().equals(currentName))  templateConfig = userConfig;
      if (currentName.equals(userName)) {
        List<NewUserConfig.Query> queries = userConfig.getQueries();
        importQueries(queriesHome, queries);
        userFound = true;
        break;
      }
    }
    if (!userFound) {
      //use template conf
      List<NewUserConfig.Query> queries = templateConfig.getQueries();
      importQueries(queriesHome, queries);
    }
    usersHome.save();
  }
{code}

Newer revision of class doesn't catch the exception, so usecase fail on PLF-3.5M3

{code}
  public void preSave(User user, boolean isNew)
      throws Exception {
    initSystemData(user.getUserName()); <<<< no try-catch block, due to refactoring
  }

  private void initSystemData(String userName) throws Exception{
    SessionProvider sessionProvider = WCMCoreUtils.getSystemSessionProvider();
    Node userNode = nodeHierarchyCreator_.getUserNode(sessionProvider, userName);
    Node queriesHome =  userNode.getNode(relativePath_) ;
    boolean userFound = false;
    NewUserConfig.User templateConfig = null;
    for (NewUserConfig.User userConfig : config_.getUsers()) {
      String currentName = userConfig.getUserName();
      if (config_.getTemplate().equals(currentName))  templateConfig = userConfig;
      if (currentName.equals(userName)) {
        List<NewUserConfig.Query> queries = userConfig.getQueries();
        importQueries(queriesHome, queries, userNode.getSession().getWorkspace().getName());
        userFound = true;
        break;
      }
    }
    if (!userFound) {
      //use template conf
      List<NewUserConfig.Query> queries = templateConfig.getQueries();
      importQueries(queriesHome, queries);
    }
  }
{code}

Please review core/services/src/main/java/org/exoplatform/services/cms/queries/impl/NewUserListener.java class best way is to add a check if node exists and then make a decision of removing it or skipping.

